	for await (const chunk of request as AsyncIterable<Buffer | string>) {
		const buffer = typeof chunk === 'string' ? Buffer.from(chunk, 'utf8') : chunk;
		bytes += buffer.length;
		if (bytes > MAX_API_REQUEST_BYTES) return null;
		chunks.push(buffer);
